# Methods
def greet(name)
  "Hello, #{name}!"
end

def add(a, b)
  a + b
end

puts greet('Ruby')
puts "3 + 5 = #{add(3, 5)}"

# Blocks
puts "\nEach:"
[1, 2, 3].each { |n| puts "  #{n} squared = #{n * n}" }

puts "\nTimes:"
3.times { |i| puts "  iteration #{i + 1}" }

# Proc
multiply = Proc.new { |x, y| x * y }
puts "\nProc result: #{multiply.call(4, 5)}"

# Lambda
square = ->(x) { x * x }
puts "Lambda: #{square.call(6)}"

# Yield

def repeat(times)
  times.times { |i| yield i }
end

puts "\nYield:"
repeat(3) { |i| puts "  hello #{i + 1}" }
